/**
 * Measure actual Electron failure exit codes with real bounded resources, ownership and saved revisions.
 * Only the error-dialog display is replaced; no exit, filesystem, IPC or application function is mocked.
 * Symbol index (generated by tools/update-symbol-index.ts):
 * @@SYMBOL_INDEX_START
 * - variable require: line 34
 * - variable root: line 38
 * - variable output: line 39
 * - variable source: line 40
 * - variable hash: line 49
 * - variable original: line 50
 * - variable verifiedCore: line 58
 * - variable coreRoot: line 59
 * - variable coreBytes: line 60
 * - variable commit: line 86
 * - variable core: line 94
 * - variable starter: line 95
 * - variable expectedElectron: line 98
 * - variable executable: line 100
 * - variable cases: line 101
 * - function fixedEvidence: line 103
 * - function resources: line 112
 * - function run: line 162
 * - variable correct: line 216
 * @@SYMBOL_INDEX_END
 */
import assert from "node:assert/strict";
import { spawn, execFileSync } from "node:child_process";
import { createHash } from "node:crypto";
import { createRequire } from "node:module";
import fs from "node:fs";
import { tmpdir } from "node:os";
import path from "node:path";
const require = createRequire(import.meta.url);
const { readRegular, readUtf8, newFile, ancestors } = require("../files.cjs");
const { openWorkspace } = require("../state.cjs");
const { verifiedResources } = require("../protocol.cjs");
const root = path.resolve(import.meta.dirname, "../..");
const output = path.resolve(process.argv[2] ?? "");
const source = path.resolve(process.argv[3] ?? "");
if (
  process.argv.length !== 4 ||
  !output.startsWith(path.join(root, ".runtime") + path.sep) ||
  !source.startsWith(root + path.sep)
)
  throw new Error("Supply a fresh own-project proof directory and built resources.");
ancestors(path.dirname(output));
fs.mkdirSync(output);
const hash = (bytes) => createHash("sha256").update(bytes).digest("hex");
const original = JSON.parse(readUtf8(path.join(source, "SOURCE.json"), 256 * 1024));
if (
  !original.core ||
  typeof original.core !== "object" ||
  Array.isArray(original.core) ||
  Object.keys(original.core).length > 256
)
  throw new Error("A bounded original core inventory is required.");
const verifiedCore = new Map();
const coreRoot = path.join(output, "verified-core");
let coreBytes = 0;
for (const [name, expected] of Object.entries(original.core)) {
  if (
    !/^core\/(?:[A-Za-z0-9_.-]+\/)*[A-Za-z0-9_.-]+$/u.test(name) ||
    name.split("/").some((part) => part === "." || part === "..") ||
    typeof expected !== "string" ||
    !/^[a-f0-9]{64}$/u.test(expected)
  )
    throw new Error("Invalid original core path or digest.");
  const bytes = readRegular(path.join(source, name), 4 * 1024 * 1024);
  coreBytes += bytes.length;
  assert(coreBytes <= 24 * 1024 * 1024, "Core fixture byte budget exceeded");
  assert.equal(hash(bytes), expected, "Actual original core bytes differ");
  verifiedCore.set(name, bytes);
  const target = path.join(coreRoot, name);
  fs.mkdirSync(path.dirname(target), { recursive: true });
  newFile(target, bytes);
}
for (const name of [
  "core/lib/workspace.js",
  "core/lib/search.js",
  "core/lib/comparison.js",
  "core/starter.json",
  "core/package.json",
])
  assert(verifiedCore.has(name), "Complete original core is required");
const commit = execFileSync(
  "git",
  ["-c", `safe.directory=${root.replaceAll("\\", "/")}`, "rev-parse", "HEAD"],
  {
    cwd: root,
    encoding: "utf8",
  },
).trim();
const core = require(path.join(coreRoot, "core/lib/workspace.js"));
const starter = core.validateCatalog(
  core.parseCatalogJson(readUtf8(path.join(coreRoot, "core/starter.json"), core.MAX_CATALOG_BYTES)),
);
const expectedElectron = JSON.parse(readUtf8(path.join(root, "desktop/package.json"), 100000))
  .devDependencies.electron;
const executable = path.join(root, "desktop/node_modules/electron/dist/electron.exe");
const cases = [];

function fixedEvidence(profile) {
  const files = ["owner.json", "current.json"];
  for (const name of fs.readdirSync(path.join(profile, "revisions")))
    files.push("revisions/" + name);
  return Object.fromEntries(
    files.map((name) => [name, hash(readRegular(path.join(profile, name), 2 * 1024 * 1024))]),
  );
}

function resources(destination, mode) {
  fs.mkdirSync(destination);
  const metadata = {
    schema: 1,
    product: "versioned-product-knowledge-portal",
    version: "0.2.0",
    source: commit,
    sourceDirty: true,
    files: {},
    core: {},
    owner: {},
  };
  for (const [name, bytes] of verifiedCore) {
    const target = path.join(destination, name);
    fs.mkdirSync(path.dirname(target), { recursive: true });
    newFile(target, bytes);
    metadata.core[name] = hash(bytes);
  }
  const html = Buffer.from(
    '<!doctype html><html lang="en"><meta charset="utf-8"><title>Startup regression</title><h1>Real owner startup regression</h1>' +
      (mode === "timeout" ? "" : '<script src="/startup.js" defer></script>'),
  );
  const script = Buffer.from(
    "void (async()=>{const loaded=await window.portalWorkspace.load();" +
      (mode === "save-reject" || mode === "normal-control"
        ? 'const catalog=structuredClone(loaded.snapshot.catalog);catalog.products[0].description+="; accepted startup save";const saved=window.portalWorkspace.save(loaded.snapshot.revision,catalog,false);' +
          (mode === "save-reject"
            ? "void saved;await window.portalWorkspace.ready(false);"
            : "await saved;await window.portalWorkspace.ready(true);await window.portalWorkspace.quit(false);")
        : mode === "reject"
          ? "await window.portalWorkspace.ready(false);"
          : "await window.portalWorkspace.ready(true);await window.portalWorkspace.quit(false);") +
      "})();",
  );
  for (const [name, bytes] of [
    ["web/index.html", html],
    ["web/workbench/index.html", html],
    ["web/startup.js", script],
  ]) {
    const target = path.join(destination, name);
    fs.mkdirSync(path.dirname(target), { recursive: true });
    newFile(target, bytes);
    metadata.files[name] = hash(bytes);
  }
  for (const name of ["files.cjs", "main.mjs", "preload.cjs", "protocol.cjs", "state.cjs"])
    metadata.owner[name] = hash(readRegular(path.join(root, "desktop", name), 256 * 1024));
  newFile(path.join(destination, "SOURCE.json"), JSON.stringify(metadata));
  verifiedResources(destination, path.join(root, "desktop"));
}

function run(profile, builtResources) {
  // Chromium initializes its default userData before the app can admit a
  // workspace. Keep that separate test-only path comparable to a normal OS
  // profile, rather than adding the long repository/case name twice.
  const isolation = fs.mkdtempSync(path.join(tmpdir(), "portal-startup-"));
  const environment = Object.fromEntries(
    Object.entries(process.env).filter(([key]) =>
      ["PATH", "Path", "SystemRoot", "WINDIR", "COMSPEC", "PATHEXT"].includes(key),
    ),
  );
  for (const key of ["APPDATA", "LOCALAPPDATA", "HOME", "USERPROFILE", "TEMP", "TMP"]) {
    const directory = path.join(isolation, key.toLowerCase());
    fs.mkdirSync(directory);
    environment[key] = directory;
  }
  environment.PORTAL_NATIVE_RESOURCES = builtResources;
  const initialUserData = path.join(isolation, "initial-chromium");
  fs.mkdirSync(initialUserData);
  environment.PORTAL_STARTUP_TEST_USER_DATA = initialUserData;
  return new Promise((resolve, reject) => {
    const started = Date.now();
    const child = spawn(
      executable,
      [path.join(root, "desktop/tests/fatal-entry.cjs"), "--profile", profile],
      { cwd: root, env: environment, stdio: ["ignore", "pipe", "pipe"], windowsHide: true },
    );
    let stdout = "",
      stderr = "";
    const deadline = setTimeout(() => {
      reject(
        new Error(
          `Owned Electron ${child.pid} exceeded45 seconds; proof retained, no forced success`,
        ),
      );
    }, 45000);
    child.stdout.on("data", (bytes) => {
      stdout += bytes.toString("utf8");
      if (Buffer.byteLength(stdout) > 65536) reject(new Error("Owned stdout budget exceeded"));
    });
    child.stderr.on("data", (bytes) => {
      stderr += bytes.toString("utf8");
      if (Buffer.byteLength(stderr) > 65536) reject(new Error("Owned stderr budget exceeded"));
    });
    child.once("error", (error) => {
      clearTimeout(deadline);
      reject(error);
    });
    child.once("exit", (code, signal) => {
      clearTimeout(deadline);
      resolve({ code, signal, stdout, stderr, elapsedMs: Date.now() - started });
    });
  });
}

let correct = true;
for (const name of [
  "invalid-resources",
  "foreign-owner",
  "save-reject",
  "timeout",
  "normal-control",
]) {
  const directory = path.join(output, name);
  fs.mkdirSync(directory);
  const profile = path.join(directory, "profile");
  const workspace = openWorkspace(profile, [], core, starter);
  await workspace.close();
  const before = fixedEvidence(profile);
  const builtResources = path.join(directory, "resources");
  resources(builtResources, name);
  if (name === "invalid-resources") fs.unlinkSync(path.join(builtResources, "SOURCE.json"));
  const foreign = "foreign-owner-token-preserved\n";
  if (name === "foreign-owner") newFile(path.join(profile, "owner.lock"), foreign);
  const actual = await run(profile, builtResources);
  const expected = name === "normal-control" ? 0 : 1;
  const after = fixedEvidence(profile);
  const writes = name === "save-reject" || name === "normal-control";
  const baselinePreserved = Object.entries(before).every(
    ([key, value]) => (writes && key === "current.json") || after[key] === value,
  );
  let ownershipPreserved;
  if (name === "foreign-owner")
    ownershipPreserved = readUtf8(path.join(profile, "owner.lock"), 128) === foreign;
  else {
    try {
      readRegular(path.join(profile, "owner.lock"), 128);
      ownershipPreserved = false;
    } catch (error) {
      if (error.code !== "ENOENT") throw error;
      ownershipPreserved = true;
    }
  }
  let admittedSave = true;
  if (writes) {
    const pointer = JSON.parse(readUtf8(path.join(profile, "current.json"), 1024));
    const record = JSON.parse(
      readUtf8(path.join(profile, "revisions", pointer.revision + ".json"), 2 * 1024 * 1024),
    );
    admittedSave =
      Object.keys(after).length === Object.keys(before).length + 1 &&
      record.catalog.products[0].description ===
        starter.products[0].description + "; accepted startup save";
  }
  const errorObserved = actual.stdout.includes("portal-startup-error");
  const runtimeLine = actual.stdout
    .split(/\r?\n/u)
    .find((line) => line.startsWith("portal-startup-runtime "));
  const runtime = runtimeLine
    ? JSON.parse(runtimeLine.slice("portal-startup-runtime ".length))
    : null;
  const passed =
    actual.code === expected &&
    actual.signal === null &&
    baselinePreserved &&
    ownershipPreserved &&
    admittedSave &&
    runtime?.electron === expectedElectron &&
    (name === "normal-control" ? !errorObserved : errorObserved) &&
    (name !== "timeout" || actual.elapsedMs >= 30000);
  cases.push({
    name,
    expected,
    ...actual,
    baselinePreserved,
    ownershipPreserved,
    admittedSave,
    errorObserved,
    runtime,
    passed,
  });
  correct &&= passed;
}
newFile(
  path.join(output, "acceptance.json"),
  JSON.stringify(
    {
      passed: correct,
      source: commit,
      mode: "actual source-main Electron; only modal error display replaced",
      cases,
    },
    null,
    2,
  ) + "\n",
);
assert(correct, "Actual startup exit or preservation regression; see acceptance.json");
console.log("All five actual Electron startup/normal-control cases passed");
